def find_most_frequent_character(S: str) -> str:
    frequency = {}

    # Count the frequency of each character in the string
    for char in S:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

    # Find the maximum frequency
    max_frequency = max(frequency.values())

    # Find all characters with the maximum frequency
    most_frequent_chars = [char for char, count in frequency.items() if count == max_frequency]

    # Return the character that comes first alphabetically
    return min(most_frequent_chars)
